import { NextFunction, Request, Response, Router } from "express";
import { AdvanceOrderUseCase } from "../application/advance-order-use-case";
import { CancelOrderUseCase } from "../application/cancel-order-use-case";
import { ListOrdersUseCase } from "../application/list-orders-use-case";
import { PlaceOrderCommand } from "../application/order-dto";
import { PlaceOrderUseCase } from "../application/place-order-use-case";

export class OrderController {
  constructor(
    private readonly placeOrder: PlaceOrderUseCase,
    private readonly advanceOrder: AdvanceOrderUseCase,
    private readonly cancelOrder: CancelOrderUseCase,
    private readonly listOrders: ListOrdersUseCase,
  ) {}

  routes(): Router {
    const router = Router();
    router.post("/orders", this.guard((req, res) => this.place(req, res)));
    router.get("/orders", this.guard((req, res) => this.list(req, res)));
    router.post("/orders/:id/status", this.guard((req, res) => this.advance(req, res)));
    router.post("/orders/:id/cancel", this.guard((req, res) => this.cancel(req, res)));
    return router;
  }

  private place(req: Request, res: Response): void {
    const body = (req.body ?? {}) as Partial<PlaceOrderCommand>;
    const lines = Array.isArray(body.lines) ? body.lines : [];
    res.status(201).json(this.placeOrder.execute({ lines }));
  }

  private list(req: Request, res: Response): void {
    res.json(this.listOrders.execute(req.query.status));
  }

  private advance(req: Request, res: Response): void {
    const body = (req.body ?? {}) as { status?: unknown };
    res.json(this.advanceOrder.execute(String(req.params.id), body.status));
  }

  private cancel(req: Request, res: Response): void {
    res.json(this.cancelOrder.execute(String(req.params.id)));
  }

  private guard(handler: (req: Request, res: Response) => void) {
    return (req: Request, res: Response, next: NextFunction): void => {
      try {
        handler(req, res);
      } catch (error) {
        next(error);
      }
    };
  }
}

