import { AdvanceOrderUseCase } from "../application/advance-order-use-case";
import { CancelOrderUseCase } from "../application/cancel-order-use-case";
import { ListOrdersUseCase } from "../application/list-orders-use-case";
import { PlaceOrderUseCase } from "../application/place-order-use-case";
import { OrderRepository } from "../domain/order-repository";
import { ProductRepository } from "../domain/product-repository";
import { StockAllocationService } from "../domain/stock-allocation-service";
import { OrderController } from "./order-controller";

export function createOrderController(
  orders: OrderRepository,
  products: ProductRepository,
): OrderController {
  const stock = new StockAllocationService(products);
  return new OrderController(
    new PlaceOrderUseCase(orders, stock),
    new AdvanceOrderUseCase(orders),
    new CancelOrderUseCase(orders, stock),
    new ListOrdersUseCase(orders),
  );
}

